<script setup lang="ts">
import {ref} from 'vue'
import type {MtrResult} from '../tools/mtr'
const props=defineProps<{en:boolean;data:MtrResult|null;error?:{code:string;message:string}|null}>();const t=(zh:string,en:string)=>props.en?en:zh;const n=(v:number|null|undefined)=>v==null?'—':v.toFixed(2);const expanded=ref<number|null>(null)
</script>
<template><div class="mtr-results structured">
<p v-if="!data">{{t('开始后显示逐跳观测；打开页面不会发送探测。','Start to observe hops. Opening this page sends no probes.')}}</p>
<template v-if="data"><p><strong>MTR · {{data.target}}</strong> → {{data.resolved_target??'—'}}</p>
<p>{{t('目标到达轮次','Target reached cycles')}}: {{data.stats.target_reached_cycles}} / {{data.stats.cycles_completed}} · {{n(data.stats.target_reach_percent)}}% · {{t('开始轮次','Started cycles')}} {{data.stats.cycles_started}} · {{t('采样缺口','Gaps')}} {{data.stats.gaps}}</p>
<p>{{t('观测窗口','Observation window')}}: {{data.started_at}} → {{data.ended_at}} · {{data.duration_ms}} ms · {{data.target_outcome}}<span v-if="data.partial"> · {{t('部分结果','Partial result')}}</span></p>
<p class="mtr-semantic">{{t('中间跳未回应率不等于转发丢包率；不同 TTL 的 RTT 差不等于单链路延迟。','Intermediate no-response is not forwarding loss; RTT differences between TTLs are not link latency.')}}</p>
<div class="table-scroll"><table class="mtr-table"><thead><tr><th>TTL</th><th>{{t('响应地址','Responders')}}</th><th>{{t('发送 / 响应 / 超时 / 中断','Sent / resp / timeout / interrupted')}}</th><th>{{t('未回应 %','No response %')}}</th><th>{{t('最近 / 最小 / 平均 / 最大 ms','Last / min / avg / max ms')}}</th><th>{{t('RTT 抖动 ms','RTT jitter ms')}}</th></tr></thead><tbody><template v-for="h in data.hops" :key="h.ttl"><tr><td>{{h.ttl}}</td><td><button class="quiet" @click="expanded=expanded===h.ttl?null:h.ttl">{{h.responders.map(r=>r.address).join(', ')||'—'}}</button><small>{{h.last_status}}</small></td><td>{{h.sent}} / {{h.responses}} / {{h.timeouts}} / {{h.interrupted}}</td><td>{{n(h.no_response_percent)}}</td><td>{{n(h.rtt.last_ms)}} / {{n(h.rtt.min_ms)}} / {{n(h.rtt.avg_ms)}} / {{n(h.rtt.max_ms)}}</td><td>{{n(h.rtt.jitter_ms)}}<small>{{h.rtt.jitter_pairs}} {{t('有效相邻对','valid adjacent pairs')}}</small></td></tr><tr v-if="expanded===h.ttl"><td colspan="6"><p v-for="r in h.responders" :key="r.address">{{r.address}} · {{r.responses}} {{t('响应','responses')}} · {{t('最小 / 平均 / 最大 / 抖动 ms','min / avg / max / jitter ms')}}: {{n(r.rtt.min_ms)}} / {{n(r.rtt.avg_ms)}} / {{n(r.rtt.max_ms)}} / {{n(r.rtt.jitter_ms)}}</p><p v-if="h.untracked_responses">{{t('响应者预览外响应','Responses outside responder preview')}}: {{h.untracked_responses}}</p></td></tr></template></tbody></table></div>
<p>{{t('抖动：同一 TTL、同一响应者连续有效 RTT 差绝对值的均值。超时、缺口或响应者变化断开计算；无有效相邻对显示 —。','Jitter: mean absolute adjacent RTT change for the same TTL and responder. Timeout, gap or responder change breaks continuity; no valid pair shows —.')}}</p>
<details v-if="data.names?.length"><summary>{{t('PTR 名称（独立证据）','PTR names (separate evidence)')}}</summary><p v-for="row in data.names" :key="row.address">{{row.address}} · {{row.names.join(', ')||'—'}} · {{row.status}}</p><p>{{t('名称不证明设备身份；反查与 ICMP 路径独立。','Names do not prove identity; PTR is independent of ICMP routing.')}}</p></details>
<details><summary>{{t('响应地址变化时间线','Responder change timeline')}} · {{data.stats.path_changes}}</summary><p v-for="(change,i) in data.path_changes" :key="i">{{change.observed_at}} · TTL {{change.ttl}} · #{{change.cycle}} · {{change.previous}} → {{change.address}}</p><p>{{t('变化可能来自 ECMP，不证明唯一物理路径改变。','Changes may reflect ECMP; they do not prove a unique physical route changed.')}}</p></details>
<details><summary>{{t('采样缺口与预览范围','Sampling gaps and preview scope')}}</summary><p v-for="(gap,i) in data.gaps" :key="i">{{gap.observed_at}} · {{gap.duration_ms}} ms · {{gap.reason}}</p><p>{{t('近期样本 / 已淘汰','Recent samples / dropped')}}: {{data.samples.length}} / {{data.samples_dropped}} · {{t('变化 / 缺口淘汰','Changes / gaps dropped')}}: {{data.changes_dropped}} / {{data.gaps_dropped}}</p><p>{{t('每 TTL 最多 16 个响应者，最近 256 个样本/变化/缺口。统计由核心累计；预览淘汰不改变统计。休眠检测为启发式，物理休眠仍需平台验收。','At most 16 responders per TTL and 256 recent samples/changes/gaps. Core counters survive preview eviction. Sleep detection is heuristic; physical suspend still needs platform acceptance.')}}</p></details>
<p>{{t('ICMP 限速、ECMP、往返路径不对称均可能影响结果；未实现 Paris traceroute。源地址仅表示配置的绑定；反查默认关闭，启用后为独立 UDP 观察。','ICMP rate limiting, ECMP and asymmetric paths can affect results; no Paris traceroute. Source denotes requested IP binding. PTR is off by default and uses independent UDP observations.')}}</p>
</template><p v-if="error" class="result-error">{{error.code}} · {{error.message}}</p></div></template>
<style scoped>.mtr-results{min-width:0;overflow-wrap:anywhere}.mtr-table{min-width:680px}.mtr-table th,.mtr-table td{white-space:normal}.mtr-table small{display:block}.mtr-semantic{font-weight:600}.mtr-results details{margin:12px 0}.mtr-results summary{cursor:pointer}</style>
